SELECT (SELECT COUNT(*) FROM life_profiles) AS profiles, (SELECT COUNT(*) FROM life_entries) AS entries, (SELECT COUNT(*) FROM life_resources) AS resources, (SELECT COUNT(*) FROM life_auth_user) AS auth_users, (SELECT COUNT(*) FROM life_ai_reviews) AS review_attempts, (SELECT COUNT(*) FROM life_review_jobs) AS review_jobs, (SELECT COUNT(*) FROM life_reminder_outbox) AS reminders, (SELECT COALESCE(SUM(cost_micros),0) FROM life_ai_reviews) AS measured_micros, (SELECT COALESCE(SUM(CASE WHEN cost_micros IS NULL THEN reserved_micros ELSE 0 END),0) FROM life_ai_reviews) AS held_micros;
